@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  font-family: Inter, system-ui, Avenir, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  font-weight: 400;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
}

import { createContext, useContext, useEffect, useState } from 'react'
import toast from 'react-hot-toast'

const CartContext = createContext()

export const useCart = () => {
  const context = useContext(CartContext)
  if (!context) {
    throw new Error('useCart must be used within a CartProvider')
  }
  return context
}

export const CartProvider = ({ children }) => {
  const [cartItems, setCartItems] = useState(() => {
    const savedCart = localStorage.getItem('shoeshop_cart')
    return savedCart ? JSON.parse(savedCart) : []
  })

  useEffect(() => {
    localStorage.setItem('shoeshop_cart', JSON.stringify(cartItems))
  }, [cartItems])

  const addToCart = (product, size) => {
    setCartItems((prevItems) => {
      const existingItem = prevItems.find(
        (item) => item.id === product.id && item.size === size
      )
      if (existingItem) {
        toast.success('কার্টে পরিমাণ বাড়ানো হয়েছে')
        return prevItems.map((item) =>
          item.id === product.id && item.size === size
            ? { ...item, quantity: item.quantity + 1 }
            : item
        )
      }
      toast.success('কার্টে যোগ করা হয়েছে')
      return [...prevItems, { ...product, size, quantity: 1 }]
    })
  }

  const removeFromCart = (id, size) => {
    setCartItems((prevItems) =>
      prevItems.filter((item) => !(item.id === id && item.size === size))
    )
    toast.success('কার্ট থেকে মুছে ফেলা হয়েছে')
  }

  const updateQuantity = (id, size, quantity) => {
    if (quantity <= 0) {
      removeFromCart(id, size)
      return
    }
    setCartItems((prevItems) =>
      prevItems.map((item) =>
        item.id === id && item.size === size ? { ...item, quantity } : item
      )
    )
  }

  const clearCart = () => {
    setCartItems([])
  }

  const getCartTotal = () => {
    return cartItems.reduce((total, item) => total + item.price * item.quantity, 0)
  }

  const getCartCount = () => {
    return cartItems.reduce((count, item) => count + item.quantity, 0)
  }

  return (
    <CartContext.Provider
      value={{
        cartItems,
        addToCart,
        removeFromCart,
        updateQuantity,
        clearCart,
        getCartTotal,
        getCartCount,
      }}
    >
      {children}
    </CartContext.Provider>
  )
}

import { createContext, useContext, useEffect, useState } from 'react'
import toast from 'react-hot-toast'

const AuthContext = createContext()

export const useAuth = () => {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider')
  }
  return context
}

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(() => {
    const savedUser = localStorage.getItem('shoeshop_user')
    return savedUser ? JSON.parse(savedUser) : null
  })

  const [users, setUsers] = useState(() => {
    const savedUsers = localStorage.getItem('shoeshop_users')
    if (savedUsers) return JSON.parse(savedUsers)
    // Default admin account
    const defaultAdmin = [
      {
        id: 1,
        name: 'Admin',
        email: 'admin@shoeshop.com',
        password: 'admin123',
        role: 'admin',
        phone: '',
        address: ''
      }
    ]
    localStorage.setItem('shoeshop_users', JSON.stringify(defaultAdmin))
    return defaultAdmin
  })

  const [orders, setOrders] = useState(() => {
    const savedOrders = localStorage.getItem('shoeshop_orders')
    return savedOrders ? JSON.parse(savedOrders) : []
  })

  useEffect(() => {
    localStorage.setItem('shoeshop_user', JSON.stringify(user))
  }, [user])

  useEffect(() => {
    localStorage.setItem('shoeshop_users', JSON.stringify(users))
  }, [users])

  useEffect(() => {
    localStorage.setItem('shoeshop_orders', JSON.stringify(orders))
  }, [orders])

  const register = (name, email, password, phone = '') => {
    const existingUser = users.find((u) => u.email === email)
    if (existingUser) {
      toast.error('এই ইমেইল দিয়ে ইতিমধ্যে একাউন্ট আছে')
      return false
    }
    const newUser = {
      id: Date.now(),
      name,
      email,
      password,
      phone,
      address: '',
      role: 'user'
    }
    setUsers([...users, newUser])
    setUser(newUser)
    toast.success('রেজিস্ট্রেশন সফল হয়েছে')
    return true
  }

  const login = (email, password) => {
    const foundUser = users.find((u) => u.email === email && u.password === password)
    if (foundUser) {
      setUser(foundUser)
      toast.success('লগইন সফল হয়েছে')
      return foundUser
    }
    toast.error('ভুল ইমেইল বা পাসওয়ার্ড')
    return null
  }

  const logout = () => {
    setUser(null)
    localStorage.removeItem('shoeshop_user')
    toast.success('লগআউট সফল হয়েছে')
  }

  const placeOrder = (orderData) => {
    const newOrder = {
      id: Date.now(),
      ...orderData,
      userId: user?.id,
      userName: user?.name,
      userEmail: user?.email,
      status: 'Pending',
      createdAt: new Date().toISOString(),
      statusHistory: [
        { status: 'Pending', date: new Date().toISOString(), note: 'অর্ডার গ্রহণ করা হয়েছে' }
      ]
    }
    setOrders([newOrder, ...orders])
    toast.success('অর্ডার সফলভাবে সম্পন্ন হয়েছে')
    return newOrder
  }

  const updateOrderStatus = (orderId, newStatus) => {
    setOrders(
      orders.map((order) => {
        if (order.id === orderId) {
          const statusNotes = {
            'Pending': 'অর্ডার গ্রহণ করা হয়েছে',
            'Confirmed': 'অর্ডার কনফার্ম করা হয়েছে',
            'Packed': 'প্যাকেজিং করা হয়েছে',
            'Shipped': 'শিপিং করা হয়েছে',
            'Out for Delivery': 'ডেলিভারির জন্য পাঠানো হয়েছে',
            'Delivered': 'ডেলিভারি সম্পন্ন হয়েছে',
            'Cancelled': 'অর্ডার বাতিল করা হয়েছে'
          }
          return {
            ...order,
            status: newStatus,
            statusHistory: [
              ...(order.statusHistory || []),
              { status: newStatus, date: new Date().toISOString(), note: statusNotes[newStatus] }
            ]
          }
        }
        return order
      })
    )
    toast.success('অর্ডার স্ট্যাটাস আপডেট করা হয়েছে')
  }

  const getUserOrders = () => {
    if (!user) return []
    return orders.filter((order) => order.userId === user.id)
  }

  return (
    <AuthContext.Provider
      value={{
        user,
        users,
        orders,
        register,
        login,
        logout,
        placeOrder,
        updateOrderStatus,
        getUserOrders,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

import { Link } from 'react-router-dom'
import { ShoppingCart } from 'lucide-react'
import { useCart } from '../context/CartContext'
import toast from 'react-hot-toast'

const ProductCard = ({ product }) => {
  const { addToCart } = useCart()

  const handleAddToCart = (e) => {
    e.preventDefault()
    if (product.sizes && product.sizes.length > 0) {
      addToCart(product, product.sizes[0])
    } else {
      toast.error('সাইজ নির্বাচন করুন')
    }
  }

  return (
    <Link to={`/product/${product.id}`} className="group">
      <div className="bg-white rounded-lg shadow-md overflow-hidden hover:shadow-lg transition-shadow duration-300">
        <div className="relative overflow-hidden h-64">
          <img
            src={product.image}
            alt={product.name}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
          />
        </div>
        <div className="p-4">
          <p className="text-sm text-gray-500 mb-1">{product.category}</p>
          <h3 className="text-lg font-semibold text-gray-900 mb-2 line-clamp-1">
            {product.name}
          </h3>
          <div className="flex items-center justify-between">
            <span className="text-xl font-bold text-gray-900">৳{product.price}</span>
            <button
              onClick={handleAddToCart}
              className="bg-gray-900 text-white p-2 rounded hover:bg-gray-800 transition"
              title="কার্টে যোগ করুন"
            >
              <ShoppingCart size={20} />
            </button>
          </div>
        </div>
      </div>
    </Link>
  )
}

export default ProductCard

import { useState } from 'react'
import ProductCard from '../components/ProductCard'
import { products, categories } from '../data/products'

const Products = () => {
  const [selectedCategory, setSelectedCategory] = useState('All')
  const [priceRange, setPriceRange] = useState('all')

  const filteredProducts = products.filter((product) => {
    const categoryMatch = selectedCategory === 'All' || product.category === selectedCategory
    const priceMatch =
      priceRange === 'all' ||
      (priceRange === 'low' && product.price < 4000) ||
      (priceRange === 'mid' && product.price >= 4000 && product.price < 6000) ||
      (priceRange === 'high' && product.price >= 6000)
    return categoryMatch && priceMatch
  })

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <h1 className="text-3xl font-bold text-gray-900 mb-8">সকল জুতা</h1>

      <div className="flex flex-col md:flex-row gap-8">
        {/* Filters */}
        <aside className="w-full md:w-64 space-y-6">
          <div>
            <h3 className="font-semibold text-gray-900 mb-3">ক্যাটেগরি</h3>
            <div className="space-y-2">
              {categories.map((category) => (
                <button
                  key={category}
                  onClick={() => setSelectedCategory(category)}
                  className={`block w-full text-left px-3 py-2 rounded transition ${
                    selectedCategory === category
                      ? 'bg-gray-900 text-white'
                      : 'text-gray-700 hover:bg-gray-100'
                  }`}
                >
                  {category === 'All' ? 'সকল' : category}
                </button>
              ))}
            </div>
          </div>

          <div>
            <h3 className="font-semibold text-gray-900 mb-3">দাম অনুযায়ী</h3>
            <div className="space-y-2">
              <button
                onClick={() => setPriceRange('all')}
                className={`block w-full text-left px-3 py-2 rounded transition ${
                  priceRange === 'all'
                    ? 'bg-gray-900 text-white'
                    : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                সকল দাম
              </button>
              <button
                onClick={() => setPriceRange('low')}
                className={`block w-full text-left px-3 py-2 rounded transition ${
                  priceRange === 'low'
                    ? 'bg-gray-900 text-white'
                    : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                ৳০ - ৳৩৯৯৯
              </button>
              <button
                onClick={() => setPriceRange('mid')}
                className={`block w-full text-left px-3 py-2 rounded transition ${
                  priceRange === 'mid'
                    ? 'bg-gray-900 text-white'
                    : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                ৳৪০০০ - ৳৫৯৯৯
              </button>
              <button
                onClick={() => setPriceRange('high')}
                className={`block w-full text-left px-3 py-2 rounded transition ${
                  priceRange === 'high'
                    ? 'bg-gray-900 text-white'
                    : 'text-gray-700 hover:bg-gray-100'
                }`}
              >
                ৳৬০০০+
              </button>
            </div>
          </div>
        </aside>

        {/* Products Grid */}
        <div className="flex-1">
          <p className="text-gray-600 mb-4">{filteredProducts.length} টি প্রোডাক্ট পাওয়া গেছে</p>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
            {filteredProducts.map((product) => (
              <ProductCard key={product.id} product={product} />
            ))}
          </div>
          {filteredProducts.length === 0 && (
            <div className="text-center py-12">
              <p className="text-gray-500 text-lg">কোন প্রোডাক্ট পাওয়া যায়নি</p>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

export default Products

import { useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ShoppingCart, ArrowLeft } from 'lucide-react'
import { products } from '../data/products'
import { useCart } from '../context/CartContext'
import toast from 'react-hot-toast'

const ProductDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const { addToCart } = useCart()
  const product = products.find((p) => p.id === parseInt(id))
  const [selectedSize, setSelectedSize] = useState('')

  if (!product) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 text-center">
        <p className="text-xl text-gray-600">প্রোডাক্ট পাওয়া যায়নি</p>
        <button
          onClick={() => navigate('/products')}
          className="mt-4 text-gray-900 hover:underline"
        >
          সকল প্রোডাক্ট দেখুন
        </button>
      </div>
    )
  }

  const handleAddToCart = () => {
    if (!selectedSize) {
      toast.error('অনুগ্রহ করে সাইজ নির্বাচন করুন')
      return
    }
    addToCart(product, parseInt(selectedSize))
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <button
        onClick={() => navigate(-1)}
        className="flex items-center text-gray-700 hover:text-gray-900 mb-6"
      >
        <ArrowLeft size={20} className="mr-2" />
        পিছনে যান
      </button>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="aspect-square overflow-hidden rounded-lg">
          <img
            src={product.image}
            alt={product.name}
            className="w-full h-full object-cover"
          />
        </div>

        <div>
          <p className="text-gray-500 mb-2">{product.category}</p>
          <h1 className="text-3xl font-bold text-gray-900 mb-4">{product.name}</h1>
          <p className="text-2xl font-bold text-gray-900 mb-6">৳{product.price}</p>
          <p className="text-gray-700 mb-6 leading-relaxed">{product.description}</p>

          <div className="mb-6">
            <h3 className="font-semibold text-gray-900 mb-3">সাইজ নির্বাচন করুন</h3>
            <div className="flex flex-wrap gap-2">
              {product.sizes.map((size) => (
                <button
                  key={size}
                  onClick={() => setSelectedSize(size.toString())}
                  className={`px-4 py-2 border rounded transition ${
                    selectedSize === size.toString()
                      ? 'bg-gray-900 text-white border-gray-900'
                      : 'border-gray-300 text-gray-700 hover:border-gray-900'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          <button
            onClick={handleAddToCart}
            className="w-full md:w-auto flex items-center justify-center bg-gray-900 text-white px-8 py-3 rounded-lg hover:bg-gray-800 transition"
          >
            <ShoppingCart size={20} className="mr-2" />
            কার্টে যোগ করুন
          </button>
        </div>
      </div>
    </div>
  )
}

export default ProductDetail

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'

const Login = () => {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const { login } = useAuth()
  const navigate = useNavigate()

  const handleSubmit = (e) => {
    e.preventDefault()
    const user = login(email, password)
    if (user) {
      if (user.role === 'admin') {
        navigate('/admin')
      } else {
        navigate('/')
      }
    }
  }

  return (
    <div className="max-w-md mx-auto px-4 py-16">
      <div className="bg-white border rounded-lg p-8">
        <h1 className="text-2xl font-bold text-gray-900 mb-6 text-center">লগইন</h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-gray-700 mb-2">ইমেইল</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <div>
            <label className="block text-gray-700 mb-2">পাসওয়ার্ড</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <button
            type="submit"
            className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-gray-800 transition"
          >
            লগইন করুন
          </button>
        </form>
        <p className="text-center text-gray-600 mt-4">
          একাউন্ট নেই?{' '}
          <Link to="/register" className="text-gray-900 hover:underline">
            রেজিস্ট্রেশন করুন
          </Link>
        </p>
        <div className="mt-4 p-3 bg-gray-100 rounded text-sm text-gray-700">
          <p className="font-semibold">ডেমো অ্যাডমিন:</p>
          <p>ইমেইল: admin@shoeshop.com</p>
          <p>পাসওয়ার্ড: admin123</p>
        </div>
      </div>
    </div>
  )
}

export default Login

import { useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'
import { useAuth } from '../context/AuthContext'

const Register = () => {
  const [name, setName] = useState('')
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [phone, setPhone] = useState('')
  const { register } = useAuth()
  const navigate = useNavigate()

  const handleSubmit = (e) => {
    e.preventDefault()
    const success = register(name, email, password, phone)
    if (success) {
      navigate('/')
    }
  }

  return (
    <div className="max-w-md mx-auto px-4 py-16">
      <div className="bg-white border rounded-lg p-8">
        <h1 className="text-2xl font-bold text-gray-900 mb-6 text-center">রেজিস্ট্রেশন</h1>
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-gray-700 mb-2">পূর্ণ নাম</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <div>
            <label className="block text-gray-700 mb-2">ইমেইল</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <div>
            <label className="block text-gray-700 mb-2">মোবাইল নম্বর</label>
            <input
              type="tel"
              value={phone}
              onChange={(e) => setPhone(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <div>
            <label className="block text-gray-700 mb-2">পাসওয়ার্ড</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
              required
            />
          </div>
          <button
            type="submit"
            className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-gray-800 transition"
          >
            রেজিস্ট্রেশন করুন
          </button>
        </form>
        <p className="text-center text-gray-600 mt-4">
          ইতিমধ্যে একাউন্ট আছে?{' '}
          <Link to="/login" className="text-gray-900 hover:underline">
            লগইন করুন
          </Link>
        </p>
      </div>
    </div>
  )
}

export default Register

import { useParams, Link } from 'react-router-dom'
import { ArrowLeft, Check } from 'lucide-react'
import { useAuth } from '../context/AuthContext'

const OrderTracking = () => {
  const { orderId } = useParams()
  const { orders } = useAuth()
  const order = orders.find((o) => o.id === parseInt(orderId))

  if (!order) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 text-center">
        <p className="text-xl text-gray-600">অর্ডার পাওয়া যায়নি</p>
        <Link to="/my-orders" className="mt-4 text-gray-900 hover:underline">
          আমার অর্ডারে ফিরে যান
        </Link>
      </div>
    )
  }

  const statusSteps = [
    { key: 'Pending', label: 'অর্ডার গ্রহণ' },
    { key: 'Confirmed', label: 'কনফার্ম' },
    { key: 'Packed', label: 'প্যাকেজিং' },
    { key: 'Shipped', label: 'শিপিং' },
    { key: 'Out for Delivery', label: 'ডেলিভারির জন্য বের' },
    { key: 'Delivered', label: 'ডেলিভারি সম্পন্ন' }
  ]

  const currentStatusIndex = statusSteps.findIndex((step) => step.key === order.status)

  return (
    <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <Link to="/my-orders" className="flex items-center text-gray-700 hover:text-gray-900 mb-6">
        <ArrowLeft size={20} className="mr-2" />
        আমার অর্ডারে ফিরে যান
      </Link>

      <div className="bg-white border rounded-lg p-6 mb-6">
        <h1 className="text-2xl font-bold text-gray-900 mb-2">অর্ডার ট্র্যাকিং</h1>
        <p className="text-gray-600">অর্ডার আইডি: #{order.id}</p>
        <p className="text-gray-600">
          তারিখ: {new Date(order.createdAt).toLocaleString('bn-BD')}
        </p>
      </div>

      {/* Status Timeline */}
      <div className="bg-white border rounded-lg p-6 mb-6">
        <h2 className="text-xl font-bold text-gray-900 mb-6">অর্ডার স্ট্যাটাস</h2>
        <div className="space-y-4">
          {statusSteps.map((step, index) => {
            const isCompleted = index <= currentStatusIndex
            const isCurrent = index === currentStatusIndex
            return (
              <div key={step.key} className="flex gap-4">
                <div className="flex flex-col items-center">
                  <div
                    className={`w-10 h-10 rounded-full flex items-center justify-center ${
                      isCompleted
                        ? 'bg-green-500 text-white'
                        : 'bg-gray-200 text-gray-400'
                    } ${isCurrent ? 'ring-4 ring-green-100' : ''}`}
                  >
                    {isCompleted ? <Check size={20} /> : index + 1}
                  </div>
                  {index < statusSteps.length - 1 && (
                    <div
                      className={`w-0.5 h-12 ${
                        index < currentStatusIndex ? 'bg-green-500' : 'bg-gray-200'
                      }`}
                    />
                  )}
                </div>
                <div className="flex-1 pb-8">
                  <h3
                    className={`font-semibold ${
                      isCompleted ? 'text-gray-900' : 'text-gray-400'
                    }`}
                  >
                    {step.label}
                  </h3>
                  {isCurrent && (
                    <p className="text-sm text-green-600 mt-1">বর্তমান স্ট্যাটাস</p>
                  )}
                </div>
              </div>
            )
          })}
        </div>
      </div>

      {/* Order Details */}
      <div className="bg-white border rounded-lg p-6 mb-6">
        <h2 className="text-xl font-bold text-gray-900 mb-4">অর্ডার বিস্তারিত</h2>
        <div className="space-y-3 mb-4">
          {order.items.map((item) => (
            <div key={`${item.id}-${item.size}`} className="flex gap-3 pb-3 border-b">
              <img src={item.image} alt={item.name} className="w-16 h-16 object-cover rounded" />
              <div className="flex-1">
                <p className="text-gray-900 font-medium">{item.name}</p>
                <p className="text-sm text-gray-500">সাইজ: {item.size} | Qty: {item.quantity}</p>
              </div>
              <span className="text-gray-900">৳{item.price * item.quantity}</span>
            </div>
          ))}
        </div>
        <div className="space-y-2">
          <div className="flex justify-between text-gray-700">
            <span>সাবটোটাল</span>
            <span>৳{order.subtotal}</span>
          </div>
          <div className="flex justify-between text-gray-700">
            <span>ডেলিভারি চার্জ</span>
            <span>৳{order.deliveryCharge}</span>
          </div>
          <div className="border-t pt-2 flex justify-between font-bold text-gray-900 text-lg">
            <span>মোট</span>
            <span>৳{order.total}</span>
          </div>
        </div>
      </div>

      {/* Shipping Info */}
      <div className="bg-white border rounded-lg p-6">
        <h2 className="text-xl font-bold text-gray-900 mb-4">ডেলিভারি তথ্য</h2>
        <div className="space-y-2 text-gray-700">
          <p><span className="font-medium">নাম:</span> {order.shippingAddress.fullName}</p>
          <p><span className="font-medium">মোবাইল:</span> {order.shippingAddress.phone}</p>
          <p><span className="font-medium">শহর:</span> {order.shippingAddress.city}</p>
          <p><span className="font-medium">ঠিকানা:</span> {order.shippingAddress.address}</p>
          <p><span className="font-medium">পেমেন্ট মেথড:</span> {order.paymentMethod === 'cod' ? 'Cash on Delivery' : order.paymentMethod.toUpperCase()}</p>
        </div>
      </div>
    </div>
  )
}

export default OrderTracking

import { useEffect } from 'react'
import { Outlet, useNavigate, Link, useLocation } from 'react-router-dom'
import { LayoutDashboard, Package, FolderTree, ShoppingBag, Users, LogOut } from 'lucide-react'
import { useAuth } from '../../context/AuthContext'

const AdminLayout = () => {
  const { user, logout } = useAuth()
  const navigate = useNavigate()
  const location = useLocation()

  useEffect(() => {
    if (!user || user.role !== 'admin') {
      navigate('/login')
    }
  }, [user, navigate])

  if (!user || user.role !== 'admin') {
    return null
  }

  const handleLogout = () => {
    logout()
    navigate('/')
  }

  const menuItems = [
    { path: '/admin', icon: LayoutDashboard, label: 'ড্যাশবোর্ড' },
    { path: '/admin/products', icon: Package, label: 'প্রোডাক্ট' },
    { path: '/admin/categories', icon: FolderTree, label: 'ক্যাটেগরি' },
    { path: '/admin/orders', icon: ShoppingBag, label: 'অর্ডার' },
    { path: '/admin/users', icon: Users, label: 'ইউজার' },
  ]

  return (
    <div className="min-h-screen bg-gray-100">
      <div className="flex">
        {/* Sidebar */}
        <aside className="w-64 bg-gray-900 text-white min-h-screen">
          <div className="p-4 border-b border-gray-800">
            <h2 className="text-xl font-bold">অ্যাডমিন প্যানেল</h2>
            <p className="text-sm text-gray-400 mt-1">ShoeShop</p>
          </div>
          <nav className="p-4 space-y-2">
            {menuItems.map((item) => {
              const Icon = item.icon
              const isActive = location.pathname === item.path
              return (
                <Link
                  key={item.path}
                  to={item.path}
                  className={`flex items-center gap-3 px-4 py-2 rounded transition ${
                    isActive
                      ? 'bg-white text-gray-900'
                      : 'text-gray-300 hover:bg-gray-800 hover:text-white'
                  }`}
                >
                  <Icon size={20} />
                  <span>{item.label}</span>
                </Link>
              )
            })}
            <button
              onClick={handleLogout}
              className="flex items-center gap-3 px-4 py-2 rounded text-gray-300 hover:bg-gray-800 hover:text-white w-full transition"
            >
              <LogOut size={20} />
              <span>লগআউট</span>
            </button>
          </nav>
        </aside>

        {/* Main Content */}
        <main className="flex-1 p-8">
          <Outlet />
        </main>
      </div>
    </div>
  )
}

export default AdminLayout

import { useState } from 'react'
import { Plus, Edit, Trash2 } from 'lucide-react'

const AdminCategories = () => {
  const [categories, setCategories] = useState(['Running', 'Casual', 'Lifestyle', 'Training'])
  const [showModal, setShowModal] = useState(false)
  const [editingCategory, setEditingCategory] = useState(null)
  const [categoryName, setCategoryName] = useState('')

  const handleAdd = () => {
    setEditingCategory(null)
    setCategoryName('')
    setShowModal(true)
  }

  const handleEdit = (category) => {
    setEditingCategory(category)
    setCategoryName(category)
    setShowModal(true)
  }

  const handleDelete = (category) => {
    if (confirm('আপনি কি নিশ্চিতভাবে এই ক্যাটেগরি মুছে ফেলতে চান?')) {
      setCategories(categories.filter((c) => c !== category))
    }
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    if (editingCategory) {
      setCategories(categories.map((c) => (c === editingCategory ? categoryName : c)))
    } else {
      if (!categories.includes(categoryName)) {
        setCategories([...categories, categoryName])
      }
    }
    setShowModal(false)
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold text-gray-900">ক্যাটেগরি ম্যানেজমেন্ট</h1>
        <button
          onClick={handleAdd}
          className="flex items-center bg-gray-900 text-white px-4 py-2 rounded hover:bg-gray-800 transition"
        >
          <Plus size={20} className="mr-2" />
          নতুন ক্যাটেগরি যোগ করুন
        </button>
      </div>

      <div className="bg-white rounded-lg shadow overflow-hidden">
        <table className="w-full">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">ক্যাটেগরির নাম</th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase">অ্যাকশন</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-gray-200">
            {categories.map((category) => (
              <tr key={category}>
                <td className="px-6 py-4 text-gray-900">{category}</td>
                <td className="px-6 py-4">
                  <div className="flex items-center gap-2">
                    <button onClick={() => handleEdit(category)} className="text-blue-600 hover:text-blue-800">
                      <Edit size={18} />
                    </button>
                    <button onClick={() => handleDelete(category)} className="text-red-600 hover:text-red-800">
                      <Trash2 size={18} />
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {showModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h2 className="text-xl font-bold text-gray-900 mb-4">
              {editingCategory ? 'ক্যাটেগরি এডিট করুন' : 'নতুন ক্যাটেগরি যোগ করুন'}
            </h2>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="block text-gray-700 mb-2">ক্যাটেগরির নাম</label>
                <input
                  type="text"
                  value={categoryName}
                  onChange={(e) => setCategoryName(e.target.value)}
                  className="w-full px-4 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
                  required
                />
              </div>
              <div className="flex gap-3">
                <button
                  type="submit"
                  className="flex-1 bg-gray-900 text-white py-2 rounded-lg hover:bg-gray-800 transition"
                >
                  {editingCategory ? 'আপডেট' : 'যোগ করুন'}
                </button>
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="flex-1 bg-gray-200 text-gray-900 py-2 rounded-lg hover:bg-gray-300 transition"
                >
                  বাতিল
                </button>
              </div>
              </form>
          </div>
        </div>
      )}
    </div>
  )
}

export default AdminCategories

export const formatPrice = (price) => {
  return `৳${price.toLocaleString('bn-BD')}`
}

