import { createContext, useContext, useEffect, useState } from 'react'
import toast from 'react-hot-toast'

const ReviewContext = createContext()

export const useReview = () => {
  const context = useContext(ReviewContext)
  if (!context) {
    throw new Error('useReview must be used within a ReviewProvider')
  }
  return context
}

export const ReviewProvider = ({ children }) => {
  const [reviews, setReviews] = useState(() => {
    const savedReviews = localStorage.getItem('shoeshop_reviews')
    return savedReviews ? JSON.parse(savedReviews) : []
  })

  useEffect(() => {
    localStorage.setItem('shoeshop_reviews', JSON.stringify(reviews))
  }, [reviews])

  const addReview = (reviewData) => {
    const existingReview = reviews.find(
      (r) => r.productId === reviewData.productId && r.userId === reviewData.userId
    )
    if (existingReview) {
      toast.error('আপনি ইতিমধ্যে এই প্রোডাক্টে রিভিউ দিয়েছেন')
      return false
    }

    const newReview = {
      id: Date.now(),
      ...reviewData,
      createdAt: new Date().toISOString(),
    }

    setReviews([newReview, ...reviews])
    toast.success('রিভিউ সফলভাবে জমা দেওয়া হয়েছে')
    return true
  }

  const deleteReview = (reviewId) => {
    setReviews(reviews.filter((r) => r.id !== reviewId))
    toast.success('রিভিউ মুছে ফেলা হয়েছে')
  }

  const getProductReviews = (productId) => {
    return reviews.filter((r) => r.productId === parseInt(productId))
  }

  const getAverageRating = (productId) => {
    const productReviews = getProductReviews(productId)
    if (productReviews.length === 0) return 0
    const sum = productReviews.reduce((total, review) => total + review.rating, 0)
    return (sum / productReviews.length).toFixed(1)
  }

  const getReviewCount = (productId) => {
    return getProductReviews(productId).length
  }

  const hasUserReviewed = (productId, userId) => {
    return reviews.some((r) => r.productId === parseInt(productId) && r.userId === userId)
  }

  return (
    <ReviewContext.Provider
      value={{
        reviews,
        addReview,
        deleteReview,
        getProductReviews,
        getAverageRating,
        getReviewCount,
        hasUserReviewed,
      }}
    >
      {children}
    </ReviewContext.Provider>
  )
}

