import { useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { ShoppingCart, ArrowLeft, Star } from 'lucide-react'
import { products } from '../data/products'
import { useCart } from '../context/CartContext'
import { useAuth } from '../context/AuthContext'
import { useReview } from '../context/ReviewContext'
import toast from 'react-hot-toast'

const ProductDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const { addToCart } = useCart()
  const { user } = useAuth()
  const { addReview, getProductReviews, getAverageRating, getReviewCount, hasUserReviewed } = useReview()
  const product = products.find((p) => p.id === parseInt(id))
  const [selectedSize, setSelectedSize] = useState('')
  const [selectedImage, setSelectedImage] = useState(0)
  const [rating, setRating] = useState(5)
  const [comment, setComment] = useState('')
  const [hoverRating, setHoverRating] = useState(0)

  const productImages = product?.images || (product?.image ? [product.image] : [])
  const reviews = product ? getProductReviews(product.id) : []
  const avgRating = product ? getAverageRating(product.id) : 0
  const reviewCount = product ? getReviewCount(product.id) : 0
  const alreadyReviewed = product && user ? hasUserReviewed(product.id, user.id) : false

  if (!product) {
    return (
      <div className="max-w-7xl mx-auto px-4 py-16 text-center">
        <p className="text-xl text-gray-600">প্রোডাক্ট পাওয়া যায়নি</p>
        <button
          onClick={() => navigate('/products')}
          className="mt-4 text-gray-900 hover:underline"
        >
          সকল প্রোডাক্ট দেখুন
        </button>
      </div>
    )
  }

  const handleAddToCart = () => {
    if (!selectedSize) {
      toast.error('অনুগ্রহ করে সাইজ নির্বাচন করুন')
      return
    }
    addToCart(product, parseInt(selectedSize))
  }

  const handleSubmitReview = (e) => {
    e.preventDefault()
    if (!user) {
      toast.error('রিভিউ দিতে লগইন করুন')
      navigate('/login')
      return
    }
    if (!comment.trim()) {
      toast.error('কমেন্ট লিখুন')
      return
    }
    const success = addReview({
      productId: product.id,
      userId: user.id,
      userName: user.name,
      rating,
      comment: comment.trim(),
    })
    if (success) {
      setComment('')
      setRating(5)
    }
  }

  const renderStars = (ratingValue, interactive = false) => {
    return (
      <div className="flex gap-1">
        {[1, 2, 3, 4, 5].map((star) => (
          <button
            key={star}
            type={interactive ? 'button' : undefined}
            onClick={interactive ? () => setRating(star) : undefined}
            onMouseEnter={interactive ? () => setHoverRating(star) : undefined}
            onMouseLeave={interactive ? () => setHoverRating(0) : undefined}
            className={interactive ? 'cursor-pointer' : ''}
            disabled={!interactive}
          >
            <Star
              size={interactive ? 28 : 18}
              className={`${
                star <= (interactive ? hoverRating || rating : ratingValue)
                  ? 'fill-yellow-400 text-yellow-400'
                  : 'text-gray-300'
              }`}
            />
          </button>
        ))}
      </div>
    )
  }

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
      <button
        onClick={() => navigate(-1)}
        className="flex items-center text-gray-700 hover:text-gray-900 mb-6"
      >
        <ArrowLeft size={20} className="mr-2" />
        পিছনে যান
      </button>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-12">
        <div>
          <div className="aspect-square overflow-hidden rounded-lg mb-4">
            <img
              src={productImages[selectedImage]}
              alt={product.name}
              className="w-full h-full object-cover"
            />
          </div>
          {productImages.length > 1 && (
            <div className="flex gap-2">
              {productImages.map((img, index) => (
                <button
                  key={index}
                  onClick={() => setSelectedImage(index)}
                  className={`w-20 h-20 rounded-lg overflow-hidden border-2 transition ${
                    selectedImage === index ? 'border-gray-900' : 'border-gray-200 hover:border-gray-400'
                  }`}
                >
                  <img src={img} alt={`${product.name} ${index + 1}`} className="w-full h-full object-cover" />
                </button>
              ))}
            </div>
          )}
        </div>

        <div>
          <p className="text-gray-500 mb-2">{product.category}</p>
          <h1 className="text-3xl font-bold text-gray-900 mb-2">{product.name}</h1>
          <div className="flex items-center gap-2 mb-4">
            {renderStars(avgRating)}
            <span className="text-gray-600">
              {avgRating > 0 ? avgRating : '0.0'} ({reviewCount} টি রিভিউ)
            </span>
          </div>
          <p className="text-2xl font-bold text-gray-900 mb-6">৳{product.price}</p>
          <p className="text-gray-700 mb-6 leading-relaxed">{product.description}</p>

          <div className="mb-6">
            <h3 className="font-semibold text-gray-900 mb-3">সাইজ নির্বাচন করুন</h3>
            <div className="flex flex-wrap gap-2">
              {product.sizes.map((size) => (
                <button
                  key={size}
                  onClick={() => setSelectedSize(size.toString())}
                  className={`px-4 py-2 border rounded transition ${
                    selectedSize === size.toString()
                      ? 'bg-gray-900 text-white border-gray-900'
                      : 'border-gray-300 text-gray-700 hover:border-gray-900'
                  }`}
                >
                  {size}
                </button>
              ))}
            </div>
          </div>

          <button
            onClick={handleAddToCart}
            className="w-full md:w-auto flex items-center justify-center bg-gray-900 text-white px-8 py-3 rounded-lg hover:bg-gray-800 transition"
          >
            <ShoppingCart size={20} className="mr-2" />
            কার্টে যোগ করুন
          </button>
        </div>
      </div>

      {/* Reviews Section */}
      <div className="border-t pt-12">
        <h2 className="text-2xl font-bold text-gray-900 mb-6">গ্রাহকের রিভিউ</h2>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          <div className="lg:col-span-1">
            <div className="bg-white border rounded-lg p-6">
              <div className="text-center mb-4">
                <div className="text-4xl font-bold text-gray-900 mb-2">{avgRating > 0 ? avgRating : '0.0'}</div>
                <div className="flex justify-center mb-2">{renderStars(avgRating)}</div>
                <p className="text-gray-600">{reviewCount} টি রিভিউ</p>
              </div>

              {user && !alreadyReviewed ? (
                <form onSubmit={handleSubmitReview} className="space-y-4 mt-6 pt-6 border-t">
                  <h3 className="font-semibold text-gray-900">রিভিউ লিখুন</h3>
                  <div>
                    <label className="block text-gray-700 mb-2">রেটিং</label>
                    {renderStars(rating, true)}
                  </div>
                  <div>
                    <label className="block text-gray-700 mb-2">আপনার মতামত</label>
                    <textarea
                      value={comment}
                      onChange={(e) => setComment(e.target.value)}
                      rows="4"
                      className="w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
                      placeholder="এই প্রোডাক্ট সম্পর্কে আপনার অভিজ্ঞতা লিখুন..."
                      required
                    ></textarea>
                  </div>
                  <button
                    type="submit"
                    className="w-full bg-gray-900 text-white py-2 rounded-lg hover:bg-gray-800 transition"
                  >
                    রিভিউ সাবমিট করুন
                  </button>
                </form>
              ) : user && alreadyReviewed ? (
                <div className="mt-6 pt-6 border-t text-center text-gray-600">
                  <p>আপনি ইতিমধ্যে এই প্রোডাক্টে রিভিউ দিয়েছেন</p>
                </div>
              ) : (
                <div className="mt-6 pt-6 border-t text-center">
                  <p className="text-gray-600 mb-3">রিভিউ দিতে লগইন করুন</p>
                  <button
                    onClick={() => navigate('/login')}
                    className="text-gray-900 hover:underline font-medium"
                  >
                    লগইন করুন
                  </button>
                </div>
              )}
            </div>
          </div>

          <div className="lg:col-span-2">
            <div className="space-y-4">
              {reviews.length === 0 ? (
                <div className="text-center py-8 text-gray-500">
                  <p>এখনো কোন রিভিউ নেই। প্রথম রিভিউ দিন!</p>
                </div>
              ) : (
                reviews.map((review) => (
                  <div key={review.id} className="bg-white border rounded-lg p-4">
