                <td className="px-6 py-4 text-gray-900">{review.userName}</td>
                <td className="px-6 py-4">{renderStars(review.rating)}</td>
                <td className="px-6 py-4 text-gray-600 max-w-xs truncate">{review.comment}</td>
                <td className="px-6 py-4 text-gray-600">
                  {new Date(review.createdAt).toLocaleDateString('bn-BD')}
                </td>
                <td className="px-6 py-4">
                  <button
                    onClick={() => {
                      if (confirm('আপনি কি নিশ্চিতভাবে এই রিভিউটি মুছে ফেলতে চান?')) {
                        deleteReview(review.id)
                      }
                    }}
                    className="text-red-600 hover:text-red-800"
                  >
                    <Trash2 size={18} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {reviews.length === 0 && (
          <div className="text-center py-8 text-gray-500">কোন রিভিউ নেই</div>
        )}
      </div>
    </div>
  )
}

export default AdminReviews

