import { useState } from 'react'
import { Plus, Edit, Trash2, X, Upload, Link as LinkIcon } from 'lucide-react'
import { products as initialProducts } from '../../data/products'

const AdminProducts = () => {
  const [products, setProducts] = useState(initialProducts)
  const [showModal, setShowModal] = useState(false)
  const [editingProduct, setEditingProduct] = useState(null)
  const [formData, setFormData] = useState({
    name: '',
    price: '',
    images: [],
    imageUrl: '',
    category: '',
    description: '',
    sizes: ''
  })
  const [uploadMethod, setUploadMethod] = useState('file') // 'file' or 'url'

  const handleAdd = () => {
    setEditingProduct(null)
    setFormData({
      name: '',
      price: '',
      images: [],
      imageUrl: '',
      category: '',
      description: '',
      sizes: ''
    })
    setUploadMethod('file')
    setShowModal(true)
  }

  const handleEdit = (product) => {
    setEditingProduct(product)
    const productImages = product.images || (product.image ? [product.image] : [])
    setFormData({
      name: product.name,
      price: product.price,
      images: productImages,
      imageUrl: '',
      category: product.category,
      description: product.description,
      sizes: product.sizes.join(', ')
    })
    setUploadMethod('file')
    setShowModal(true)
  }

  const handleDelete = (id) => {
    if (confirm('আপনি কি নিশ্চিতভাবে এই প্রোডাক্টটি মুছে ফেলতে চান?')) {
      setProducts(products.filter((p) => p.id !== id))
    }
  }

  const handleImageUpload = (e) => {
    const files = Array.from(e.target.files)
    if (files.length === 0) return

    files.forEach((file) => {
      if (file.size > 5 * 1024 * 1024) {
        alert('ছবির সাইজ ৫ MB এর কম হতে হবে')
        return
      }
      const reader = new FileReader()
      reader.onloadend = () => {
        setFormData((prev) => ({
          ...prev,
          images: [...prev.images, reader.result]
        }))
      }
      reader.readAsDataURL(file)
    })
    e.target.value = null
  }

  const handleAddImageUrl = () => {
    if (!formData.imageUrl.trim()) {
      alert('ইমেজ URL লিখুন')
      return
    }
    setFormData((prev) => ({
      ...prev,
      images: [...prev.images, formData.imageUrl.trim()],
      imageUrl: ''
    }))
  }

  const removeImage = (index) => {
    setFormData((prev) => ({
      ...prev,
      images: prev.images.filter((_, i) => i !== index)
    }))
  }

  const handleSubmit = (e) => {
    e.preventDefault()

    if (formData.images.length === 0) {
      alert('অনুগ্রহ করে অন্তত একটি ছবি যোগ করুন')
      return
    }

    const productData = {
      name: formData.name,
      price: parseInt(formData.price),
      images: formData.images,
      image: formData.images[0],
      category: formData.category,
      description: formData.description,
      sizes: formData.sizes.split(',').map((s) => parseInt(s.trim())).filter((s) => !isNaN(s))
    }

    if (editingProduct) {
      setProducts(products.map((p) => (p.id === editingProduct.id ? { ...productData, id: editingProduct.id } : p)))
    } else {
      setProducts([...products, { ...productData, id: Date.now() }])
    }
    setShowModal(false)
  }

