export const HomeContentProvider = ({ children }) => {
  const [homeContent, setHomeContent] = useState(() => {
    const saved = localStorage.getItem('homeContent')
    if (saved) {
      try {
        return JSON.parse(saved)
      } catch {
        return defaultHomeContent
      }
    }
    return defaultHomeContent
  })

  useEffect(() => {
    localStorage.setItem('homeContent', JSON.stringify(homeContent))
  }, [homeContent])

  const updateHero = (heroData) => {
    setHomeContent((prev) => ({
      ...prev,
      hero: { ...prev.hero, ...heroData }
    }))
  }

  const updateCategories = (categories) => {
    setHomeContent((prev) => ({
      ...prev,
      categories: categories
    }))
  }

  const resetToDefault = () => {
    setHomeContent(defaultHomeContent)
    localStorage.removeItem('homeContent')
  }

  return (
    <HomeContentContext.Provider value={{ homeContent, updateHero, updateCategories, resetToDefault }}>
      {children}
    </HomeContentContext.Provider>
  )
}

export const useHomeContent = () => {
  const context = useContext(HomeContentContext)
  if (!context) {
    throw new Error('useHomeContent must be used within a HomeContentProvider')
  }
  return context
}

