import { createContext, useContext, useState, useEffect } from 'react'
import { products as initialProductsData } from '../data/products'

const ProductsContext = createContext()

export const useProducts = () => {
  const context = useContext(ProductsContext)
  if (!context) {
    throw new Error('useProducts must be used within a ProductsProvider')
  }
  return context
}

export const ProductsProvider = ({ children }) => {
  const [products, setProducts] = useState(() => {
    const savedProducts = localStorage.getItem('shoeshop_products')
    if (savedProducts) {
      try {
        return JSON.parse(savedProducts)
      } catch {
        return initialProductsData
      }
    }
    return initialProductsData
  })

  useEffect(() => {
    localStorage.setItem('shoeshop_products', JSON.stringify(products))
  }, [products])

  const addProduct = (product) => {
    const newProduct = { ...product, id: Date.now() }
    setProducts((prev) => [...prev, newProduct])
  }

  const updateProduct = (id, updatedProduct) => {
    setProducts((prev) =>
      prev.map((p) => (p.id === parseInt(id) ? { ...updatedProduct, id: parseInt(id) } : p))
    )
  }

  const deleteProduct = (id) => {
    setProducts((prev) => prev.filter((p) => p.id !== id))
  }

  const getProductById = (id) => {
    return products.find((p) => p.id === parseInt(id))
  }

  return (
    <ProductsContext.Provider
      value={{
        products,
        addProduct,
        updateProduct,
        deleteProduct,
        getProductById
      }}
    >
      {children}
    </ProductsContext.Provider>
  )
}

