export const CategoryMenuProvider = ({ children }) => {
  const [categoryMenu, setCategoryMenu] = useState(() => {
    const saved = localStorage.getItem('shoeshop_category_menu')
    if (saved) {
      try {
        return JSON.parse(saved)
      } catch {
        return defaultCategoryMenu
      }
    }
    return defaultCategoryMenu
  })

  useEffect(() => {
    localStorage.setItem('shoeshop_category_menu', JSON.stringify(categoryMenu))
  }, [categoryMenu])

  const updateCategoryMenu = (menu) => {
    setCategoryMenu(menu)
  }

  const resetCategoryMenu = () => {
    setCategoryMenu(defaultCategoryMenu)
    localStorage.removeItem('shoeshop_category_menu')
  }

  return (
    <CategoryMenuContext.Provider value={{ categoryMenu, updateCategoryMenu, resetCategoryMenu }}>
      {children}
    </CategoryMenuContext.Provider>
  )
}

export const useCategoryMenu = () => {
  const context = useContext(CategoryMenuContext)
  if (!context) {
    throw new Error('useCategoryMenu must be used within a CategoryMenuProvider')
  }
  return context
}

import { useState } from 'react'
import { useCategoryMenu } from '../../context/CategoryMenuContext'
import { Plus, Edit, Trash2, ChevronDown, ChevronRight, Save, RotateCcw } from 'lucide-react'
import toast from 'react-hot-toast'

const AdminCategoryMenu = () => {
  const { categoryMenu, updateCategoryMenu, resetCategoryMenu } = useCategoryMenu()
  const [menu, setMenu] = useState(JSON.parse(JSON.stringify(categoryMenu)))
  const [expandedMain, setExpandedMain] = useState([])
  const [expandedSub, setExpandedSub] = useState([])
  const [editingMain, setEditingMain] = useState(null)
  const [editingSub, setEditingSub] = useState(null)
  const [editingChild, setEditingChild] = useState(null)

  const toggleMain = (id) => {
    setExpandedMain((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]))
  }

  const toggleSub = (id) => {
    setExpandedSub((prev) => (prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id]))
  }

  const addMainCategory = () => {
    const newMain = {
      id: Date.now(),
      name: 'নতুন ক্যাটেগরি',
      slug: 'new-category',
      children: []
    }
    setMenu([...menu, newMain])
    setEditingMain(newMain.id)
  }

  const updateMainCategory = (id, field, value) => {
    setMenu(menu.map((m) => (m.id === id ? { ...m, [field]: value } : m)))
  }

  const deleteMainCategory = (id) => {
    if (confirm('এই মূল ক্যাটেগরি মুছে ফেলতে চান?')) {
      setMenu(menu.filter((m) => m.id !== id))
    }
  }

  const addSubCategory = (mainId) => {
    const newSub = {
      id: Date.now(),
      name: 'নতুন সাব-ক্যাটেগরি',
      slug: 'new-sub-category',
      children: []
    }
    setMenu(
      menu.map((m) => (m.id === mainId ? { ...m, children: [...m.children, newSub] } : m))
    )
    setEditingSub(newSub.id)
  }

  const updateSubCategory = (mainId, subId, field, value) => {
    setMenu(
      menu.map((m) =>
        m.id === mainId
          ? {
              ...m,
              children: m.children.map((s) => (s.id === subId ? { ...s, [field]: value } : s))
            }
          : m
      )
    )
  }

  const deleteSubCategory = (mainId, subId) => {
    if (confirm('এই সাব-ক্যাটেগরি মুছে ফেলতে চান?')) {
      setMenu(
        menu.map((m) =>
          m.id === mainId ? { ...m, children: m.children.filter((s) => s.id !== subId) } : m
        )
      )
    }
  }

  const addChild = (mainId, subId) => {
    setMenu(
      menu.map((m) =>
        m.id === mainId
          ? {
              ...m,
              children: m.children.map((s) =>
                s.id === subId ? { ...s, children: [...(s.children || []), 'নতুন আইটেম'] } : s
              )
            }
          : m
      )
    )
  }

  const updateChild = (mainId, subId, index, value) => {
    setMenu(
      menu.map((m) =>
        m.id === mainId
          ? {
              ...m,
              children: m.children.map((s) =>
                s.id === subId
                  ? {
                      ...s,
                      children: (s.children || []).map((c, i) => (i === index ? value : c))
                    }
                  : s
              )
            }
          : m
      )
    )
  }

  const deleteChild = (mainId, subId, index) => {
    setMenu(
      menu.map((m) =>
        m.id === mainId
          ? {
              ...m,
              children: m.children.map((s) =>
                s.id === subId
                  ? { ...s, children: (s.children || []).filter((_, i) => i !== index) }
                  : s
              )
            }
          : m
      )
    )
  }

  const handleSave = () => {
    updateCategoryMenu(menu)
    toast.success('ক্যাটেগরি মেনু আপডেট করা হয়েছে')
  }

  const handleReset = () => {
    if (confirm('ডিফল্ট ক্যাটেগরি মেনুতে ফিরিয়ে নিতে চান?')) {
      resetCategoryMenu()
      setMenu(JSON.parse(JSON.stringify(categoryMenu)))
      toast.success('ডিফল্টে ফিরিয়ে নেওয়া হয়েছে')
    }
  }

  return (
    <div className="max-w-6xl mx-auto">
      <div className="flex items-center justify-between mb-8">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">মেগা মেনু ম্যানেজমেন্ট</h1>
          <p className="text-gray-600 mt-1">মূল ক্যাটেগরি, সাব-ক্যাটেগরি ও ব্র্যান্ড/টাইপ যোগ করুন</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={handleReset}
            className="flex items-center gap-2 px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition"
          >
            <RotateCcw size={18} />
            ডিফল্টে ফিরিয়ে নিন
          </button>
          <button
            onClick={handleSave}
            className="flex items-center gap-2 px-6 py-2 bg-gradient-to-r from-gray-900 to-gray-800 text-white rounded-lg hover:from-gray-800 hover:to-gray-700 transition shadow-md"
          >
            <Save size={18} />
            সেভ করুন
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-100 mb-4">
        <div className="p-6">
          <button
            onClick={addMainCategory}
            className="flex items-center gap-2 px-4 py-2 bg-gray-900 text-white rounded-lg hover:bg-gray-800 transition"
          >
            <Plus size={18} />
            নতুন মূল ক্যাটেগরি যোগ করুন
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {menu.map((mainCat) => (
          <div key={mainCat.id} className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
            <div className="p-4 flex items-center gap-3">
              <button onClick={() => toggleMain(mainCat.id)} className="text-gray-600">
                {expandedMain.includes(mainCat.id) ? <ChevronDown size={20} /> : <ChevronRight size={20} />}
              </button>
              {editingMain === mainCat.id ? (
                <div className="flex-1 flex gap-2">
                  <input
                    type="text"
                    value={mainCat.name}
                    onChange={(e) => updateMainCategory(mainCat.id, 'name', e.target.value)}
                    className="flex-1 px-3 py-1.5 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
                    placeholder="মূল ক্যাটেগরির নাম"
                  />
                  <input
                    type="text"
                    value={mainCat.slug}
                    onChange={(e) => updateMainCategory(mainCat.id, 'slug', e.target.value)}
                    className="w-40 px-3 py-1.5 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-gray-900"
                    placeholder="slug"
                  />
                  <button onClick={() => setEditingMain(null)} className="px-3 py-1.5 bg-gray-900 text-white rounded-lg text-sm">
                    ঠিক আছে
                  </button>
                </div>
              ) : (
                <div className="flex-1 flex items-center justify-between">
                  <span className="font-semibold text-gray-900">{mainCat.name}</span>
                  <div className="flex items-center gap-2">
                    <button onClick={() => setEditingMain(mainCat.id)} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded">
                      <Edit size={16} />
                    </button>
                    <button onClick={() => deleteMainCategory(mainCat.id)} className="p-1.5 text-red-600 hover:bg-red-50 rounded">
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              )}
            </div>

            {expandedMain.includes(mainCat.id) && (
              <div className="px-4 pb-4 pl-12 space-y-2">
                <button
                  onClick={() => addSubCategory(mainCat.id)}
                  className="flex items-center gap-1.5 text-sm text-gray-900 hover:underline"
                >
                  <Plus size={16} />
                  সাব-ক্যাটেগরি যোগ করুন
                </button>

                {(mainCat.children || []).map((subCat) => (
                  <div key={subCat.id} className="border border-gray-200 rounded-lg">
                    <div className="p-3 flex items-center gap-2">
                      <button onClick={() => toggleSub(subCat.id)} className="text-gray-600">
                        {expandedSub.includes(subCat.id) ? <ChevronDown size={18} /> : <ChevronRight size={18} />}
                      </button>
                      {editingSub === subCat.id ? (
                        <div className="flex-1 flex gap-2">
                          <input
                            type="text"
                            value={subCat.name}
                            onChange={(e) => updateSubCategory(mainCat.id, subCat.id, 'name', e.target.value)}
                            className="flex-1 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-1 focus:ring-gray-900 text-sm"
                          />
                          <input
                            type="text"
                            value={subCat.slug}
                            onChange={(e) => updateSubCategory(mainCat.id, subCat.id, 'slug', e.target.value)}
                            className="w-32 px-2 py-1 border border-gray-300 rounded focus:outline-none focus:ring-1 focus:ring-gray-900 text-sm"
                          />
                          <button onClick={() => setEditingSub(null)} className="px-2 py-1 bg-gray-900 text-white rounded text-xs">
                            ঠিক আছে
                          </button>
                        </div>
                      ) : (
                        <div className="flex-1 flex items-center justify-between">
                          <span className="text-gray-800 text-sm">{subCat.name}</span>
                          <div className="flex items-center gap-1">
                            <button onClick={() => setEditingSub(subCat.id)} className="p-1 text-blue-600 hover:bg-blue-50 rounded">
                              <Edit size={14} />
                            </button>
                            <button onClick={() => deleteSubCategory(mainCat.id, subCat.id)} className="p-1 text-red-600 hover:bg-red-50 rounded">
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                      )}
                    </div>

                    {expandedSub.includes(subCat.id) && (
                      <div className="px-3 pb-3 pl-10">
                        <button
                          onClick={() => addChild(mainCat.id, subCat.id)}
                          className="flex items-center gap-1 text-xs text-gray-700 hover:underline mb-2"
                        >
                          <Plus size={14} />
                          ব্র্যান্ড/টাইপ যোগ করুন
                        </button>
                        <div className="flex flex-wrap gap-1.5">
                          {(subCat.children || []).map((child, idx) => (
                            <div key={idx} className="flex items-center gap-1 px-2 py-1 bg-gray-100 rounded">
                              <input
                                type="text"
                                value={child}
                                onChange={(e) => updateChild(mainCat.id, subCat.id, idx, e.target.value)}
                                className="bg-transparent text-xs focus:outline-none w-20"
                              />
                              <button onClick={() => deleteChild(mainCat.id, subCat.id, idx)} className="text-red-500 hover:text-red-700">
                                <X size={12} />
                              </button>
                            </div>
                          ))}
                        </div>
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  )
}

