import { useState, useEffect } from 'react'
import { Plus, Edit, Trash2 } from 'lucide-react'
import { categories as initialCategories } from '../../data/products'
import toast from 'react-hot-toast'

const AdminCategories = () => {
  const [categories, setCategories] = useState(() => {
    const saved = localStorage.getItem('shoeshop_simple_categories')
    if (saved) {
      try {
        return JSON.parse(saved)
      } catch {
        return initialCategories.filter((c) => c !== 'All')
      }
    }
    return initialCategories.filter((c) => c !== 'All')
  })
  const [showModal, setShowModal] = useState(false)
  const [editingCategory, setEditingCategory] = useState(null)
  const [categoryName, setCategoryName] = useState('')

  useEffect(() => {
    localStorage.setItem('shoeshop_simple_categories', JSON.stringify(categories))
  }, [categories])

  const handleAdd = () => {
    setEditingCategory(null)
    setCategoryName('')
    setShowModal(true)
  }

  const handleEdit = (category) => {
    setEditingCategory(category)
    setCategoryName(category)
    setShowModal(true)
  }

  const handleDelete = (category) => {
    if (confirm('আপনি কি নিশ্চিতভাবে এই ক্যাটেগরি মুছে ফেলতে চান?')) {
      setCategories(categories.filter((c) => c !== category))
      toast.success('ক্যাটেগরি মুছে ফেলা হয়েছে')
    }
  }

  const handleSubmit = (e) => {
    e.preventDefault()
    const trimmedName = categoryName.trim()
    if (!trimmedName) {
      toast.error('ক্যাটেগরির নাম লিখুন')
      return
    }
    if (editingCategory) {
      setCategories(categories.map((c) => (c === editingCategory ? trimmedName : c)))
      toast.success('ক্যাটেগরি আপডেট করা হয়েছে')
    } else {
      if (categories.some((c) => c.toLowerCase() === trimmedName.toLowerCase())) {
        toast.error('এই ক্যাটেগরি ইতিমধ্যে রয়েছে')
        return
      }
      setCategories([...categories, trimmedName])
      toast.success('নতুন ক্যাটেগরি যোগ করা হয়েছে')
    }
    setShowModal(false)
    setCategoryName('')
    setEditingCategory(null)
  }

